import React, { useState } from "react";
import { useDispatch } from "react-redux";
import { login } from "../../redux/auth/authSlice";
import { useNavigate, Link } from "react-router-dom";
import { setAuthToken } from "../../redux/root/api";

const Login = () => {
  const [form, setForm] = useState({ username: "", password: "" });
  const [error, setError] = useState("");
  const dispatch = useDispatch();
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");

    const res = await dispatch(login(form));

    if (res.meta.requestStatus === "fulfilled") {
      // ✅ ذخیره توکن در localStorage و تنظیم برای axios
      const token = res.payload?.token;
      if (token) {
        localStorage.setItem("token", token);
        setAuthToken(token);
      }

      // بررسی نقش کاربر
      const roles = res.payload?.roles || [];

      // اگر کاربر ادمین است، به صفحه لیست کاربران هدایت شود
      if (roles.includes("ROLE_ADMIN")) {
        navigate("/users");
      } else {
        // اگر کاربر معمولی است، به صفحه لیست کارمندان هدایت شود
        navigate("/");
      }
    } else {
      setError("نام کاربری یا رمز عبور اشتباه است");
    }
  };

  return (
    <div className="container-fluid d-flex justify-content-center align-items-center min-vh-100">
      <div className="card shadow" style={{ width: "100%", maxWidth: "400px" }}>
        <div className="card-body p-4">
          <h3 className="card-title text-center mb-4">ورود به سیستم</h3>

          {error && (
            <div className="alert alert-danger" role="alert">
              {error}
            </div>
          )}

          <form onSubmit={handleSubmit}>
            <div className="mb-3">
              <label htmlFor="username" className="form-label">
                نام کاربری
              </label>
              <input
                id="username"
                className="form-control form-control-lg"
                placeholder="نام کاربری"
                value={form.username}
                onChange={(e) => setForm({ ...form, username: e.target.value })}
                required
              />
            </div>

            <div className="mb-3">
              <label htmlFor="password" className="form-label">
                رمز عبور
              </label>
              <input
                id="password"
                className="form-control form-control-lg"
                type="password"
                placeholder="رمز عبور"
                value={form.password}
                onChange={(e) => setForm({ ...form, password: e.target.value })}
                required
              />
            </div>

            <button className="btn btn-primary btn-lg w-100 mb-3">ورود</button>

            <div className="text-center">
              <p className="mb-0">
                حساب کاربری ندارید؟{" "}
                <Link to="/signup" className="text-decoration-none">
                  ثبت نام کنید
                </Link>
              </p>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default Login;
